const SUPPORTED_THEME_PREFIXES = Object.freeze([
  'templates/',
  'sections/',
  'snippets/',
  'assets/',
  'config/settings_data.json',
  'config/settings_schema.json'
]);

function isSupportedThemeFile(filename) {
  if (!filename || typeof filename !== 'string') {
    return false;
  }

  return SUPPORTED_THEME_PREFIXES.some((prefix) => filename === prefix || filename.startsWith(prefix));
}

function getTemplateCandidates(objectType, templateSuffix) {
  if (!templateSuffix) {
    return [];
  }

  const base = `templates/${objectType}.${templateSuffix}`;
  return [`${base}.json`, `${base}.liquid`];
}

async function getDestinationThemeContext(client, config) {
  if (!client || !client.destination || !client.destination.themes) {
    return null;
  }

  const themeId = await client.destination.themes.resolveThemeId(config.destinationThemeId);
  const files = await client.destination.themes.listFiles(themeId);

  return {
    themeId,
    files,
    filenames: new Set(files.map((file) => file.filename))
  };
}

async function resolveTemplateSyncAction({
  objectType,
  templateSuffix,
  config,
  client
}) {
  if (!templateSuffix) {
    return {
      templateSuffix,
      warnings: []
    };
  }

  const candidates = getTemplateCandidates(objectType, templateSuffix);
  const warnings = [];

  try {
    const themeContext = await getDestinationThemeContext(client, config);
    if (!themeContext) {
      return { templateSuffix, warnings };
    }

    const exists = candidates.some((filename) => themeContext.filenames.has(filename));
    if (exists) {
      return { templateSuffix, warnings };
    }

    const warning = `${objectType} template "${templateSuffix}" does not exist in destination theme ${themeContext.themeId}.`;
    warnings.push(warning);

    if (config.missingTemplatePolicy === 'error') {
      return {
        templateSuffix,
        warnings,
        error: warning
      };
    }

    if (config.missingTemplatePolicy === 'clear') {
      return {
        templateSuffix: null,
        warnings
      };
    }

    return { templateSuffix, warnings };
  } catch (error) {
    return {
      templateSuffix,
      warnings: [
        `Unable to validate destination template "${templateSuffix}" for ${objectType}: ${error.message}`
      ]
    };
  }
}

function extractJsonSectionFiles(filename, content) {
  if (!filename.endsWith('.json') || !content) {
    return [];
  }

  try {
    const parsed = JSON.parse(content);
    const sections = parsed && parsed.sections ? Object.values(parsed.sections) : [];
    return sections
      .map((section) => section && section.type ? `sections/${section.type}.liquid` : null)
      .filter(Boolean);
  } catch (_error) {
    return [];
  }
}

function extractLiquidReferences(content) {
  if (!content) {
    return {
      snippets: [],
      assets: []
    };
  }

  const snippets = new Set();
  const assets = new Set();
  const renderPattern = /{%\s*(?:render|include)\s+['"]([^'"]+)['"]/g;
  const assetPattern = /(?:asset_url|asset_img_url|stylesheet_tag|script_tag)\s*[:(]?\s*['"]([^'"]+)['"]/g;

  for (const match of content.matchAll(renderPattern)) {
    snippets.add(`snippets/${match[1]}.liquid`);
  }

  for (const match of content.matchAll(assetPattern)) {
    assets.add(`assets/${match[1]}`);
  }

  return {
    snippets: [...snippets],
    assets: [...assets]
  };
}

module.exports = {
  SUPPORTED_THEME_PREFIXES,
  isSupportedThemeFile,
  getTemplateCandidates,
  getDestinationThemeContext,
  resolveTemplateSyncAction,
  extractJsonSectionFiles,
  extractLiquidReferences
};
